select
  sum(case when wf_month_key(f.[Exercise Date]) is null or wf_month_key(f.[Exercise Date]) <= {constants.workflowMonth} then f.[Exercised Qty] else 0 end) as futu_exercised_qty,
  max(c.gyre_2023_china_subplan_total) - sum(case when wf_month_key(f.[Exercise Date]) is null or wf_month_key(f.[Exercise Date]) <= {constants.workflowMonth} then f.[Exercised Qty] else 0 end) as bci_shares_held_by_futu,
  sum(case when wf_month_key(f.[Exercise Date]) is not null and wf_month_key(f.[Exercise Date]) > {constants.workflowMonth} then f.[Exercised Qty] else 0 end) as futu_exercised_after_month_qty,
  max(case when wf_month_key(f.[Exercise Date]) is not null and wf_month_key(f.[Exercise Date]) > {constants.workflowMonth} then wf_month_key(f.[Exercise Date]) else null end) as futu_latest_exercise_month
from (
  select * from {futu}
  where trim(concat('', coalesce([Employee No.], ''))) <> ''
    and trim(concat('', coalesce([Employee No.], ''))) <> '员工编号'
) f, {control_metrics} c
